CREATE TRIGGER sales_post_reference_guard BEFORE INSERT ON document_finalizations WHEN NEW.document_type='sales' AND NEW.action='POST' AND EXISTS(SELECT 1 FROM sales s WHERE s.organization_id=NEW.organization_id AND s.id=NEW.document_id AND (NOT EXISTS(SELECT 1 FROM warehouses w WHERE w.organization_id=s.organization_id AND w.id=s.warehouse_id AND w.is_active=1) OR EXISTS(SELECT 1 FROM sale_items si JOIN products p ON p.organization_id=si.organization_id AND p.id=si.product_id WHERE si.organization_id=s.organization_id AND si.sale_id=s.id AND p.is_active=0))) BEGIN SELECT RAISE(ABORT,'REFERENCE_CHANGED'); END;
